html:
{#
    AL-IHSAN HOSPITAL — LANDED COST VOUCHER
    DocType: Landed Cost Voucher

    Uses the standard ERPNext v15 fields:
      - doc.purchase_receipts
      - doc.items
      - doc.taxes
      - doc.total_taxes_and_charges
      - doc.distribute_charges_based_on
#}

{% set navy = "#10194f" %}
{% set orange = "#e36c12" %}
{% set soft = "#f6f7fb" %}
{% set border = "#cfd4df" %}
{% set text = "#121826" %}
{% set muted = "#667085" %}

{% set company_currency = frappe.db.get_value("Company", doc.company, "default_currency") or "" %}
{% set prepared_by = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner or "" %}
{% set item_total = (doc.get("items") or []) | sum(attribute="amount") %}
{% set applicable_total = (doc.get("items") or []) | sum(attribute="applicable_charges") %}
{% set landed_total = item_total + applicable_total %}
{% set status_label = "DRAFT" if doc.docstatus == 0 else ("CANCELLED" if doc.docstatus == 2 else "SUBMITTED") %}
{% set status_class = "status-draft" if doc.docstatus == 0 else ("status-cancelled" if doc.docstatus == 2 else "status-submitted") %}

<style>
    * {
        box-sizing: border-box;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    body,
    .print-format {
        margin: 0;
        color: {{ text }};
        font-family: Arial, Helvetica, sans-serif;
        font-size: 10px;
        line-height: 1.35;
    }

    .lcv-page {
        position: relative;
        width: 100%;
        max-width: 760px;
        margin: 0 auto;
        padding: 6px 18px 12px;
        background: #ffffff;
    }

    .brand-header {
        width: 100%;
        margin-bottom: 3px;
        text-align: center;
    }

    .brand-header img {
        max-width: 100%;
        height: auto;
    }

    .brand-rule {
        width: 100%;
        height: 4px;
        margin: 2px 0 12px;
        border-collapse: collapse;
    }

    .brand-rule span {
        display: inline-block;
        height: 4px;
        vertical-align: top;
    }

    .rule-navy-a { width: 20%; background: {{ navy }}; }
    .rule-orange-a { width: 17%; background: {{ orange }}; margin-left: 2%; }
    .rule-navy-b { width: 25%; background: {{ navy }}; margin-left: 2%; }
    .rule-orange-b { width: 30%; background: {{ orange }}; margin-left: 2%; }

    .company-line {
        margin: 0 0 11px;
        color: {{ navy }};
        font-size: 10px;
        font-weight: 800;
        text-transform: uppercase;
        letter-spacing: 0.45px;
    }

    .company-line span {
        color: {{ text }};
    }

    .doc-title {
        margin: 3px 0 0;
        color: {{ navy }};
        font-size: 23px;
        font-weight: 800;
        line-height: 1.15;
        text-align: center;
        text-transform: uppercase;
        letter-spacing: 4px;
    }

    .title-line {
        width: 142px;
        height: 3px;
        margin: 8px auto 9px;
        border-radius: 2px;
        background: {{ orange }};
    }

    .reference-table {
        width: 100%;
        margin-bottom: 10px;
        border-collapse: collapse;
        font-size: 11px;
    }

    .reference-table td {
        padding: 0;
        border: 0;
        vertical-align: middle;
    }

    .reference-table td:nth-child(2) {
        text-align: center;
    }

    .reference-table td:last-child {
        text-align: right;
    }

    .ref-label {
        color: {{ navy }};
        font-weight: 800;
    }

    .ref-value {
        color: {{ text }};
        font-weight: 650;
    }

    .status-pill {
        display: inline-block;
        min-width: 82px;
        padding: 4px 10px;
        border-radius: 999px;
        font-size: 9px;
        font-weight: 800;
        text-align: center;
        letter-spacing: 0.8px;
    }

    .status-draft {
        color: #8a4b08;
        background: #fff2df;
        border: 1px solid #f0b46e;
    }

    .status-submitted {
        color: #14532d;
        background: #eaf8ef;
        border: 1px solid #8fd1a4;
    }

    .status-cancelled {
        color: #991b1b;
        background: #feecec;
        border: 1px solid #efaaaa;
    }

    .info-card {
        margin-bottom: 14px;
        overflow: hidden;
        border: 2px solid {{ navy }};
        border-top: 4px solid {{ orange }};
        border-radius: 9px;
        background: {{ soft }};
    }

    .info-grid {
        display: table;
        width: 100%;
        table-layout: fixed;
        border-collapse: collapse;
    }

    .info-cell {
        display: table-cell;
        padding: 9px 11px;
        border-right: 1px solid {{ border }};
        vertical-align: top;
    }

    .info-cell:last-child {
        border-right: 0;
    }

    .info-row + .info-row {
        border-top: 1px solid {{ border }};
    }

    .info-label {
        margin-bottom: 3px;
        color: {{ navy }};
        font-size: 9px;
        font-weight: 800;
        text-transform: uppercase;
        letter-spacing: 0.35px;
    }

    .info-value {
        color: {{ text }};
        font-size: 10px;
        font-weight: 650;
        word-wrap: break-word;
    }

    .section-block {
        margin-top: 13px;
        page-break-inside: auto;
    }

    .section-heading {
        display: table;
        width: 100%;
        margin-bottom: 5px;
        border-collapse: collapse;
    }

    .section-heading > div {
        display: table-cell;
        vertical-align: middle;
    }

    .section-heading-title {
        color: {{ navy }};
        font-size: 11px;
        font-weight: 800;
        text-transform: uppercase;
        letter-spacing: 0.65px;
    }

    .section-heading-note {
        color: {{ muted }};
        font-size: 8.5px;
        text-align: right;
    }

    .data-table {
        width: 100%;
        border-collapse: collapse;
        table-layout: fixed;
        font-size: 8.6px;
    }

    .data-table thead {
        display: table-header-group;
    }

    .data-table th {
        padding: 7px 5px;
        color: #ffffff !important;
        background: {{ navy }} !important;
        border: 1px solid #ffffff;
        font-size: 8px;
        font-weight: 800;
        line-height: 1.2;
        text-align: center;
        text-transform: uppercase;
        letter-spacing: 0.25px;
    }

    .data-table th:first-child {
        border-left-color: {{ navy }};
    }

    .data-table th:last-child {
        border-right-color: {{ navy }};
    }

    .data-table td {
        padding: 6px 5px;
        border: 1px solid #9aa2b1;
        color: {{ text }};
        line-height: 1.3;
        vertical-align: top;
        word-wrap: break-word;
    }

    .data-table tbody tr {
        page-break-inside: avoid;
    }

    .data-table tbody tr:nth-child(even) {
        background: #f8f9fc;
    }

    .text-center { text-align: center; }
    .text-right { text-align: right; }
    .nowrap { white-space: nowrap; }

    .link-value {
        color: {{ navy }};
        font-weight: 750;
    }

    .item-code {
        color: {{ navy }};
        font-weight: 800;
    }

    .item-description,
    .item-description p,
    .item-description div {
        margin: 0 !important;
        padding: 0 !important;
    }

    .item-meta {
        margin-top: 3px;
        color: {{ muted }};
        font-size: 7.6px;
        line-height: 1.3;
    }

    .charge-value {
        color: {{ orange }};
        font-weight: 800;
    }

    .landed-value {
        color: {{ navy }};
        font-weight: 800;
    }

    .summary-wrap {
        width: 100%;
        margin-top: 11px;
        text-align: right;
        page-break-inside: avoid;
    }

    .summary-box {
        display: inline-block;
        width: 47%;
        min-width: 330px;
        border: 1px solid #8d96a7;
        text-align: left;
    }

    .summary-row {
        display: table;
        width: 100%;
        border-collapse: collapse;
    }

    .summary-row > span {
        display: table-cell;
        padding: 7px 9px;
        border-bottom: 1px solid {{ border }};
    }

    .summary-row > span:first-child {
        color: {{ navy }};
        font-weight: 750;
    }

    .summary-row > span:last-child {
        font-weight: 750;
        text-align: right;
    }

    .summary-row-total > span {
        color: #ffffff !important;
        background: {{ navy }} !important;
        border-bottom: 3px solid {{ orange }};
        font-size: 11px;
        font-weight: 800 !important;
    }

    .summary-row:last-child > span {
        border-bottom: 0;
    }

    .footer-note {
        width: 100%;
        margin-top: 22px;
        padding-top: 8px;
        border-top: 1px solid #d8dde6;
        color: {{ muted }};
        font-size: 8.5px;
        text-align: center;
        page-break-inside: avoid;
    }

    .footer-note strong {
        color: {{ navy }};
    }

    @media print {
        @page {
            size: A4 portrait;
            margin: 9mm 8mm 9mm;
        }

        body,
        .print-format {
            font-size: 9.5px;
        }

        .lcv-page {
            max-width: none;
            padding: 0;
        }

        .data-table th,
        .summary-row-total > span,
        .status-pill,
        .info-card,
        .brand-rule span {
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
        }
    }
</style>

<div class="lcv-page">

    <!-- Letter Head -->
    <div class="brand-header">
        {{ letter_head }}
    </div>

    <!--<div class="brand-rule" aria-hidden="true">-->
    <!--    <span class="rule-navy-a"></span><span class="rule-orange-a"></span><span class="rule-navy-b"></span><span class="rule-orange-b"></span>-->
    <!--</div>-->

    <div class="company-line">
        Company: <span>{{ doc.company or "—" }}</span>
    </div>

    <!-- Title -->
    <div class="doc-title">Landed Cost Voucher</div>
    <div class="title-line"></div>

    <!-- Main reference -->
    <table class="reference-table">
        <tr>
            <td style="width: 40%;">
                <span class="ref-label">LCV No.</span>
                <span class="ref-value">{{ doc.name or "—" }}</span>
            </td>

            <td style="width: 20%;">
                <span class="status-pill {{ status_class }}">{{ status_label }}</span>
            </td>

            <td style="width: 40%;">
                <span class="ref-label">Dated:</span>
                <span class="ref-value">
                    {% if doc.posting_date %}
                        {{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}
                    {% else %}
                        —
                    {% endif %}
                </span>
            </td>
        </tr>
    </table>

    <!-- Information card -->
    <div class="info-card">
        <div class="info-row info-grid">
            <div class="info-cell" style="width: 25%;">
                <div class="info-label">Company</div>
                <div class="info-value">{{ doc.company or "—" }}</div>
            </div>

            <div class="info-cell" style="width: 25%;">
                <div class="info-label">Posting Date</div>
                <div class="info-value">
                    {% if doc.posting_date %}
                        {{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}
                    {% else %}
                        —
                    {% endif %}
                </div>
            </div>

            <div class="info-cell" style="width: 25%;">
                <div class="info-label">Receipt Documents</div>
                <div class="info-value">{{ (doc.get("purchase_receipts") or []) | length }}</div>
            </div>

            <div class="info-cell" style="width: 25%;">
                <div class="info-label">Distribution Basis</div>
                <div class="info-value">{{ doc.distribute_charges_based_on or "—" }}</div>
            </div>
        </div>

        <div class="info-row info-grid">
            <div class="info-cell" style="width: 50%;">
                <div class="info-label">Prepared By</div>
                <div class="info-value">{{ prepared_by or "—" }}</div>
            </div>

            <div class="info-cell" style="width: 50%;">
                <div class="info-label">Amended From</div>
                <div class="info-value">{{ doc.amended_from or "—" }}</div>
            </div>
        </div>
    </div>

    <!-- Receipt documents -->
    <div class="section-block">
        <div class="section-heading">
            <div class="section-heading-title">Receipt Documents</div>
            <div class="section-heading-note">Documents whose item values receive the landed charges</div>
        </div>

        <table class="data-table">
            <colgroup>
                <col style="width: 5%;">
                <col style="width: 17%;">
                <col style="width: 24%;">
                <col style="width: 25%;">
                <col style="width: 13%;">
                <col style="width: 16%;">
            </colgroup>
            <thead>
                <tr>
                    <th>SN.</th>
                    <th>Receipt Type</th>
                    <th>Receipt Document</th>
                    <th>Supplier</th>
                    <th>Posting Date</th>
                    <th>Grand Total</th>
                </tr>
            </thead>
            <tbody>
                {% for receipt in doc.get("purchase_receipts") or [] %}
                    <tr>
                        <td class="text-center">{{ loop.index }}</td>
                        <td>{{ receipt.receipt_document_type or "—" }}</td>
                        <td><span class="link-value">{{ receipt.receipt_document or "—" }}</span></td>
                        <td>
                            {% if receipt.supplier %}
                                {{ frappe.db.get_value("Supplier", receipt.supplier, "supplier_name") or receipt.supplier }}
                            {% else %}
                                —
                            {% endif %}
                        </td>
                        <td class="text-center nowrap">
                            {% if receipt.posting_date %}
                                {{ frappe.utils.formatdate(receipt.posting_date, "dd-MM-yyyy") }}
                            {% else %}
                                —
                            {% endif %}
                        </td>
                        <td class="text-right nowrap">
                            {{ frappe.utils.fmt_money(receipt.grand_total or 0, currency=company_currency) }}
                        </td>
                    </tr>
                {% else %}
                    <tr>
                        <td colspan="6" class="text-center">No receipt documents found.</td>
                    </tr>
                {% endfor %}
            </tbody>
        </table>
    </div>

    <!-- Landed cost items -->
    <div class="section-block">
        <div class="section-heading">
            <div class="section-heading-title">Landed Cost Items</div>
            <div class="section-heading-note">Original item values and allocated landed charges</div>
        </div>

        <table class="data-table">
            <colgroup>
                <col style="width: 4%;">
                <col style="width: 14%;">
                <col style="width: 30%;">
                <col style="width: 7%;">
                <col style="width: 10%;">
                <col style="width: 11%;">
                <col style="width: 11%;">
                <col style="width: 13%;">
            </colgroup>
            <thead>
                <tr>
                    <th>SN.</th>
                    <th>Item Code</th>
                    <th>Description / Source</th>
                    <th>Qty</th>
                    <th>Rate</th>
                    <th>Amount</th>
                    <th>Charges</th>
                    <th>Landed Value</th>
                </tr>
            </thead>
            <tbody>
                {% for item in doc.get("items") or [] %}
                    <tr>
                        <td class="text-center">{{ loop.index }}</td>
                        <td><span class="item-code">{{ item.item_code or "—" }}</span></td>
                        <td>
                            <div class="item-description">{{ (item.description or "") | safe }}</div>
                            <div class="item-meta">
                                {% if item.receipt_document_type or item.receipt_document %}
                                    Source: {{ item.receipt_document_type or "Receipt" }} · {{ item.receipt_document or "—" }}
                                {% endif %}
                                {% if item.cost_center %}
                                    <br>Cost Center: {{ item.cost_center }}
                                {% endif %}
                            </div>
                        </td>
                        <td class="text-center nowrap">{{ item.qty or 0 }}</td>
                        <td class="text-right nowrap">
                            {{ frappe.utils.fmt_money(item.rate or 0, currency=company_currency) }}
                        </td>
                        <td class="text-right nowrap">
                            {{ frappe.utils.fmt_money(item.amount or 0, currency=company_currency) }}
                        </td>
                        <td class="text-right nowrap">
                            <span class="charge-value">
                                {{ frappe.utils.fmt_money(item.applicable_charges or 0, currency=company_currency) }}
                            </span>
                        </td>
                        <td class="text-right nowrap">
                            <span class="landed-value">
                                {{ frappe.utils.fmt_money((item.amount or 0) + (item.applicable_charges or 0), currency=company_currency) }}
                            </span>
                        </td>
                    </tr>
                {% else %}
                    <tr>
                        <td colspan="8" class="text-center">No landed cost items found.</td>
                    </tr>
                {% endfor %}
            </tbody>
        </table>
    </div>

    <!-- Taxes and charges -->
    <div class="section-block">
        <div class="section-heading">
            <div class="section-heading-title">Taxes and Charges</div>
            <div class="section-heading-note">Additional costs distributed across the receipt items</div>
        </div>

        <table class="data-table">
            <colgroup>
                <col style="width: 6%;">
                <col style="width: 31%;">
                <col style="width: 31%;">
                <col style="width: 16%;">
                <col style="width: 16%;">
            </colgroup>
            <thead>
                <tr>
                    <th>SN.</th>
                    <th>Expense Account</th>
                    <th>Description</th>
                    <th>Amount</th>
                    <th>Company Amount</th>
                </tr>
            </thead>
            <tbody>
                {% for tax in doc.get("taxes") or [] %}
                    <tr>
                        <td class="text-center">{{ loop.index }}</td>
                        <td>
                            <span class="link-value">
                                {{ tax.expense_account or "—" }}
                            </span>
                        </td>
                        <td>{{ tax.description or "—" }}</td>
                        <td class="text-right nowrap">
                            {{ frappe.utils.fmt_money(
                                tax.amount or 0,
                                currency=tax.account_currency or company_currency
                            ) }}
                        </td>
                        <td class="text-right nowrap">
                            {{ frappe.utils.fmt_money(
                                tax.base_amount or 0,
                                currency=company_currency
                            ) }}
                        </td>
                    </tr>
                {% else %}
                    <tr>
                        <td colspan="5" class="text-center">
                            No taxes or charges found.
                        </td>
                    </tr>
                {% endfor %}
            </tbody>
        </table>
    </div>

    <!-- Summary -->
    <div class="summary-wrap">
        <div class="summary-box">
            <div class="summary-row">
                <span>Original Item Value</span>
                <span>{{ frappe.utils.fmt_money(item_total or 0, currency=company_currency) }}</span>
            </div>

            <div class="summary-row">
                <span>Total Applicable Charges</span>
                <span>{{ frappe.utils.fmt_money(doc.total_taxes_and_charges or applicable_total or 0, currency=company_currency) }}</span>
            </div>

            <div class="summary-row">
                <span>Distribution Basis</span>
                <span>{{ doc.distribute_charges_based_on or "—" }}</span>
            </div>

            <div class="summary-row summary-row-total">
                <span>Total Landed Value</span>
                <span>{{ frappe.utils.fmt_money(landed_total or 0, currency=company_currency) }}</span>
            </div>
        </div>
    </div>

    <!-- Footer -->
    <div class="footer-note">
        <strong>{{ doc.company or "Al-Ihsan Hospital" }}</strong><br>
        This is a system-generated Landed Cost Voucher. It allocates the listed charges to the referenced receipt items.
    </div>

</div>
